Here is the source code structured specifically for a Thesis Appendix or Documentation. It is organized by module (Core, Auth, Player, Admin) to make it easy to copy and paste into your document.

### **Appendix A: Core Application Structure**

**File: `src/App.tsx`**
*Description: Main application entry point handling routing between Login, Admin, and Player views.*

```tsx
import React from 'react';
import { AnimatePresence, motion, Transition } from 'framer-motion';
import { useAppContext } from './context/AppContext';
import LoginPage from './components/LoginPage';
import AdminDashboard from './components/AdminDashboard';
import PlayerLayout from './components/PlayerLayout';
import ToastContainer from './components/ToastContainer';

const pageVariants = {
    initial: { opacity: 0, y: 20 },
    in: { opacity: 1, y: 0 },
    out: { opacity: 0, y: -20 },
};

const pageTransition: Transition = {
    type: 'tween',
    ease: 'anticipate',
    duration: 0.5,
};

const App: React.FC = () => {
    const { state } = useAppContext();
    const { user } = state;

    return (
        <div className="min-h-screen w-full bg-slate-900">
            <AnimatePresence mode="wait">
                {!user ? (
                    <motion.div
                        key="login"
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                        className="w-full"
                    >
                        <LoginPage />
                    </motion.div>
                ) : user.role === 'admin' ? (
                    <motion.div
                        key="admin"
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                        className="w-full"
                    >
                        <AdminDashboard />
                    </motion.div>
                ) : (
                    <motion.div
                        key="player"
                        initial="initial"
                        animate="in"
                        exit="out"
                        variants={pageVariants}
                        transition={pageTransition}
                        className="w-full"
                    >
                        <PlayerLayout />
                    </motion.div>
                )}
            </AnimatePresence>
            <ToastContainer />
        </div>
    );
};

export default App;
```

