### **Appendix B: Authentication System**

**File: `src/components/LoginPage.tsx`**
*Description: Handles user authentication, registration, and role-based login logic.*

```tsx
import React, { useState } from 'react';
import LogoIcon from './icons/LogoIcon';
import { useAppContext } from '../context/AppContext';

const LoginPage: React.FC = () => {
    const { login, signup, addToast, dispatch } = useAppContext();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isSigningUp, setIsSigningUp] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const handleSignInSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        setIsLoading(true);
        const result = await login(email, password);
        setIsLoading(false);

        if (result.success && result.user) {
            addToast(result.message);
            dispatch({ type: 'LOGIN_SUCCESS', payload: result.user });
        } else {
            addToast(result.message, 'error');
        }
    };

    // ... (SignUp logic similar to SignIn)

    return (
        <div className="flex items-center justify-center min-h-screen bg-slate-900 p-4">
            <div className="w-full max-w-md bg-gray-800 rounded-2xl shadow-2xl p-8 border border-gray-700">
                <div className="flex flex-col items-center space-y-4">
                    <LogoIcon />
                    <h1 className="text-3xl font-bold text-gray-100">
                        {isSigningUp ? 'Join Quest' : 'Welcome Back'}
                    </h1>
                </div>
                <form className="space-y-6 mt-6" onSubmit={handleSignInSubmit}>
                    <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="w-full px-4 py-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                        placeholder="Email"
                        required
                    />
                    <input
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className="w-full px-4 py-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                        placeholder="Password"
                        required
                    />
                    <button
                        type="submit"
                        disabled={isLoading}
                        className="w-full py-3 px-4 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-bold transition-all"
                    >
                        {isLoading ? 'Loading...' : (isSigningUp ? 'Sign Up' : 'Sign In')}
                    </button>
                </form>
                {/* Mode toggle and Admin login buttons omitted for brevity */}
            </div>
        </div>
    );
};

export default LoginPage;
```

