### **Appendix C: Player Experience & Chapter Progression**

**File: `src/components/PuzzleList.tsx`**
*Description: Displays the Quest Map. Handles chapter locking, sequential progression, and visual rendering of the user's journey.*

```tsx
import React, { useMemo } from 'react';
import { motion } from 'framer-motion';
import { useAppContext } from '../context/AppContext';
import { Puzzle } from '../lib/types';
import PuzzleIcon from './icons/PuzzleIcon';
import LockIcon from './icons/LockIcon';

// Define the Chapter Structure
const CHAPTER_META: Record<string, { title: string; subtitle: string; order: number }> = {
    'JavaScript Basics': { title: 'Chapter 1', subtitle: 'The Foundation', order: 1 },
    'Array Methods': { title: 'Chapter 2', subtitle: 'The Array Arsenal', order: 2 },
    'Asynchronous JS': { title: 'Chapter 3', subtitle: 'Async Ascension', order: 3 },
    'default': { title: 'Side Quest', subtitle: 'Extra Challenges', order: 99 }
};

const PuzzleList: React.FC = () => {
    const { state, dispatch } = useAppContext();
    const { puzzles, user } = state;

    // Sort categories by chapter order
    const sortedCategories = useMemo(() => {
        return Object.keys(puzzles).sort((a, b) => {
            const orderA = CHAPTER_META[a]?.order ?? CHAPTER_META['default'].order;
            const orderB = CHAPTER_META[b]?.order ?? CHAPTER_META['default'].order;
            return orderA - orderB;
        });
    }, [puzzles]);

    // Calculate which chapters are unlocked
    const categoryStatus = useMemo(() => {
        const status: Record<string, 'locked' | 'unlocked' | 'completed'> = {};
        let isPreviousComplete = true; 

        sortedCategories.forEach((category) => {
            const categoryPuzzles = puzzles[category];
            const solvedCount = categoryPuzzles.filter(p => user?.solvedPuzzleIds.includes(p.id)).length;
            const isComplete = solvedCount === categoryPuzzles.length && categoryPuzzles.length > 0;

            // Admin bypass or Logic check
            if (user?.role === 'admin') {
                 status[category] = isComplete ? 'completed' : 'unlocked';
            } else {
                if (isPreviousComplete) {
                    status[category] = isComplete ? 'completed' : 'unlocked';
                } else {
                    status[category] = 'locked';
                }
            }

            // If this chapter isn't complete, the NEXT one will be locked
            if (!isComplete) isPreviousComplete = false;
        });
        return status;
    }, [sortedCategories, puzzles, user]);

    const handlePuzzleClick = (puzzle: Puzzle, isLocked: boolean) => {
        if (isLocked) return;
        dispatch({ type: 'START_PUZZLE', payload: puzzle });
    };

    return (
        <div className="container mx-auto max-w-3xl py-8">
            <h1 className="text-4xl font-bold text-center text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500 mb-12">
                Quest Map
            </h1>

            <div className="relative border-l-4 border-gray-700 ml-6 md:ml-12 space-y-12">
                {sortedCategories.map((category, index) => {
                    const meta = CHAPTER_META[category] || CHAPTER_META['default'];
                    const status = categoryStatus[category];
                    const categoryPuzzles = puzzles[category];
                    const isLocked = status === 'locked';

                    return (
                        <div key={category} className="relative pl-8 md:pl-12">
                            {/* Timeline Connector Dot */}
                            <div className={`absolute -left-[1.3rem] top-0 w-10 h-10 rounded-full border-4 flex items-center justify-center bg-gray-900 z-10 
                                ${isLocked ? 'border-gray-600 text-gray-600' : 'border-blue-500 text-blue-500'}`}>
                                {isLocked ? <LockIcon className="w-5 h-5" /> : <span className="font-bold">{meta.order}</span>}
                            </div>

                            <motion.div 
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: index * 0.1 }}
                                className={`rounded-xl p-6 border ${isLocked ? 'bg-gray-800/30 border-gray-700 opacity-70 grayscale' : 'bg-gray-800/80 border-blue-900/50 shadow-lg'}`}
                            >
                                <div className="mb-4">
                                    <h2 className="text-2xl font-bold text-white">{meta.title}: {category}</h2>
                                    <p className="text-blue-300 font-medium">{meta.subtitle}</p>
                                </div>

                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    {categoryPuzzles.map((puzzle) => {
                                        const isSolved = user?.solvedPuzzleIds.includes(puzzle.id);
                                        return (
                                            <button
                                                key={puzzle.id}
                                                disabled={isLocked}
                                                onClick={() => handlePuzzleClick(puzzle, isLocked)}
                                                className={`flex items-center p-3 rounded-lg border text-left transition-all
                                                    ${isLocked 
                                                        ? 'bg-transparent border-gray-700 cursor-not-allowed' 
                                                        : isSolved 
                                                            ? 'bg-green-900/20 border-green-700 hover:bg-green-900/40' 
                                                            : 'bg-gray-700/50 border-gray-600 hover:border-blue-500 hover:bg-gray-700'
                                                    }`}
                                            >
                                                <div className={`p-2 rounded-lg mr-3 ${isSolved ? 'bg-green-500/20 text-green-400' : 'bg-gray-800 text-gray-400'}`}>
                                                    <PuzzleIcon className="w-5 h-5" />
                                                </div>
                                                <div>
                                                    <div className="font-bold text-sm text-gray-200">{puzzle.title}</div>
                                                    <div className="text-xs text-gray-400">{puzzle.points} XP • {puzzle.difficulty}</div>
                                                </div>
                                            </button>
                                        );
                                    })}
                                </div>
                            </motion.div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default PuzzleList;
```

