### **Appendix D: Administrative Dashboard**

**File: `src/components/AdminDashboard.tsx`**
*Description: Provides the navigation hub for administrators to manage content, players, and view stats.*

```tsx
import React from 'react';
import { useAppContext } from '../context/AppContext';
import PuzzleManagement from './admin/PuzzleManagement';
import PlayerManagement from './admin/PlayerManagement';
import AdminLeaderboard from './admin/AdminLeaderboard';

const AdminDashboard: React.FC = () => {
    const { state, logout, dispatch } = useAppContext();
    const { adminView } = state;

    const setAdminView = (view: any) => dispatch({ type: 'SET_ADMIN_VIEW', payload: view });

    if (adminView === 'puzzle_management') return <PuzzleManagement />;
    if (adminView === 'player_management') return <PlayerManagement />;
    if (adminView === 'leaderboard_overview') return <AdminLeaderboard />;

    return (
        <div className="min-h-screen bg-slate-900 text-white p-8">
            <header className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-bold">Admin Dashboard</h1>
                <button onClick={logout} className="px-4 py-2 bg-red-600 rounded-lg">Log Out</button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
                    <h2 className="text-xl font-semibold mb-2">Puzzle Management</h2>
                    <p className="text-gray-400 mb-4">Create, edit, and delete code challenges.</p>
                    <button onClick={() => setAdminView('puzzle_management')} className="w-full bg-blue-600 py-2 rounded">Manage</button>
                </div>

                <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
                    <h2 className="text-xl font-semibold mb-2">Player Management</h2>
                    <p className="text-gray-400 mb-4">View progress and manage user accounts.</p>
                    <button onClick={() => setAdminView('player_management')} className="w-full bg-green-600 py-2 rounded">Manage</button>
                </div>

                <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
                    <h2 className="text-xl font-semibold mb-2">Leaderboard</h2>
                    <p className="text-gray-400 mb-4">View global rankings and stats.</p>
                    <button onClick={() => setAdminView('leaderboard_overview')} className="w-full bg-yellow-600 py-2 rounded">View</button>
                </div>
            </div>
        </div>
    );
};

export default AdminDashboard;
