    | { type: 'DELETE_PUZZLE'; payload: string }
    | { type: 'ADD_CATEGORY', payload: string }
    | { type: 'EDIT_CATEGORY', payload: { oldName: string; newName: string } }
    | { type: 'DELETE_CATEGORY', payload: string }
