    | { type: 'RESET_PLAYER_PROGRESS', payload: number }
    | { type: 'ADD_TOAST'; payload: { message: string; type: 'success' | 'error' } }
    | { type: 'REMOVE_TOAST'; payload: number };

const initialState: AppState = {
