```tsx
import React, { useMemo } from 'react';
import { motion, Variants } from 'framer-motion';
import { Puzzle } from '../lib/types';
import { useAppContext } from '../context/AppContext';
import PuzzleIcon from './icons/PuzzleIcon';
import LockIcon from './icons/LockIcon';

const CHAPTER_META: Record<string, { title: string; subtitle: string; order: number }> = {
    'JavaScript Basics': { title: 'Chapter 1', subtitle: 'The Foundation', order: 1 },
    'Array Methods': { title: 'Chapter 2', subtitle: 'The Array Arsenal', order: 2 },
    'Asynchronous JS': { title: 'Chapter 3', subtitle: 'Async Ascension', order: 3 },
    'default': { title: 'Side Quest', subtitle: 'Extra Challenges', order: 99 }
};

const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
        opacity: 1,
        transition: {
            staggerChildren: 0.1,
        },
    },
};

const itemVariants: Variants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
        y: 0,
        opacity: 1,
        transition: { type: 'spring', stiffness: 50, damping: 10 },
    },
};

const PuzzleList: React.FC = () => {
    const { state, dispatch } = useAppContext();
    const { puzzles, user } = state;

    const sortedCategories = useMemo(() => {
        return Object.keys(puzzles).sort((a, b) => {
            const orderA = CHAPTER_META[a]?.order ?? CHAPTER_META['default'].order;
            const orderB = CHAPTER_META[b]?.order ?? CHAPTER_META['default'].order;
            return orderA - orderB;
        });
    }, [puzzles]);

    const categoryStatus = useMemo(() => {
        const status: Record<string, 'locked' | 'unlocked' | 'completed'> = {};
        let isPreviousComplete = true; 

        sortedCategories.forEach((category) => {
            const categoryPuzzles = puzzles[category];
            const solvedCount = categoryPuzzles.filter(p => user?.solvedPuzzleIds.includes(p.id)).length;
            const isComplete = solvedCount === categoryPuzzles.length && categoryPuzzles.length > 0;

            if (user?.role === 'admin') {
                 status[category] = isComplete ? 'completed' : 'unlocked';
            } else {
                if (isPreviousComplete) {
                    status[category] = isComplete ? 'completed' : 'unlocked';
                } else {
                    status[category] = 'locked';
                }
            }

            if (!isComplete) {
                isPreviousComplete = false;
            }
        });
        return status;
    }, [sortedCategories, puzzles, user]);

    const handlePuzzleClick = (puzzle: Puzzle, isLocked: boolean) => {
        if (isLocked) return;
        dispatch({ type: 'START_PUZZLE', payload: puzzle });
    };

    return (
        <div className="container mx-auto max-w-3xl py-8 px-4">
            <div className="text-center mb-12">
                <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500">
                    Quest Map
                </h1>
                <p className="text-gray-400 mt-2">Complete chapters to unlock new coding challenges.</p>
            </div>

            <motion.div 
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                className="relative border-l-4 border-slate-700 ml-4 md:ml-12 space-y-12 pb-12"
            >
                {sortedCategories.map((category, index) => {
                    const meta = CHAPTER_META[category] || CHAPTER_META['default'];
                    const status = categoryStatus[category];
                    const categoryPuzzles = puzzles[category];
                    const isLocked = status === 'locked';
                    const isCompleted = status === 'completed';

                    return (
                        <motion.div key={category} variants={itemVariants} className="relative pl-8 md:pl-12">
                            <div className={`absolute -left-[1.3rem] top-0 w-10 h-10 rounded-full border-4 flex items-center justify-center bg-slate-900 z-10 transition-colors duration-300
                                ${isLocked ? 'border-gray-600 text-gray-600' : 
                                  isCompleted ? 'border-green-500 text-green-500 bg-green-900/20' : 
                                  'border-blue-500 text-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.5)]'}`}>
                                {isLocked ? (
                                    <LockIcon className="w-5 h-5" />
                                ) : isCompleted ? (
                                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                                ) : (
                                    <span className="font-bold text-lg">{meta.order}</span>
                                )}
                            </div>

                            <div className={`rounded-xl p-6 border transition-all duration-300 relative overflow-hidden group
                                ${isLocked 
                                    ? 'bg-slate-800/30 border-slate-700 opacity-60 grayscale' 
                                    : 'bg-slate-800/80 border-slate-600 hover:border-blue-500/50 shadow-lg'
                                }`}>

                                {isLocked && <div className="absolute inset-0 z-20 cursor-not-allowed" title="Complete previous chapter to unlock"></div>}

                                <div className="flex justify-between items-start mb-4">
                                    <div>
                                        <h2 className="text-2xl font-bold text-slate-100 flex items-center gap-2">
                                            {meta.title}: {category}
                                        </h2>
                                        <p className="text-blue-400 font-medium text-sm uppercase tracking-wider">{meta.subtitle}</p>
                                    </div>
                                    <div className="text-right">
                                         <span className={`text-xs font-bold px-2 py-1 rounded uppercase
                                            ${isLocked ? 'bg-gray-700 text-gray-400' : 
                                              isCompleted ? 'bg-green-900/50 text-green-400' : 'bg-blue-900/50 text-blue-400'}`}>
                                            {status.toUpperCase()}
                                         </span>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                    {categoryPuzzles.map((puzzle) => {
                                        const isSolved = user?.solvedPuzzleIds.includes(puzzle.id);
                                        return (
                                            <button
                                                key={puzzle.id}
                                                onClick={() => handlePuzzleClick(puzzle, isLocked)}
                                                disabled={isLocked}
                                                className={`flex items-center p-3 rounded-lg border text-left transition-all duration-200 relative group/btn
                                                    ${isLocked 
                                                        ? 'bg-transparent border-slate-700' 
                                                        : isSolved 
                                                            ? 'bg-green-900/10 border-green-800/50 hover:bg-green-900/30' 
                                                            : 'bg-slate-700/50 border-slate-600 hover:border-blue-500 hover:bg-slate-700'
                                                    }`}
                                            >
                                                <div className={`p-2 rounded-lg mr-3 shrink-0 ${isSolved ? 'bg-green-500/10 text-green-400' : 'bg-slate-800 text-slate-400 group-hover/btn:text-blue-400'}`}>
                                                    <PuzzleIcon className="w-5 h-5" />
                                                </div>
                                                <div className="flex-grow min-w-0">
                                                    <div className={`font-bold text-sm truncate ${isSolved ? 'text-green-200' : 'text-slate-200'}`}>
                                                        {puzzle.title}
                                                    </div>
                                                    <div className="flex justify-between items-center mt-1">
                                                        <span className="text-xs text-slate-500 font-medium">{puzzle.difficulty}</span>
                                                        <span className="text-xs font-bold text-yellow-500/80">{puzzle.points} XP</span>
                                                    </div>
                                                </div>
                                                {isSolved && (
                                                    <div className="absolute right-2 top-2 text-green-500">
                                                        <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                                                    </div>
                                                )}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        </motion.div>
                    );
                })}
            </motion.div>
        </div>
    );
};

export default PuzzleList;
